RANK = {'critical': 0, 'major': 1, 'minor': 2, 'trivial': 3}

def triage_order(defects):
    ordered = sorted(defects, key=lambda d: (RANK[d['severity']], d['workaround'], -d['users'], d['id']))
    return [d['id'] for d in ordered]

import re

def group_duplicates(reports):
    groups = {}
    for rid, line in reports:
        sig = re.sub(r'\s+', ' ', re.sub(r'\d+', '#', line.lower())).strip()
        groups.setdefault(sig, []).append(rid)
    return [ids for ids in groups.values() if len(ids) >= 2]
